import{useEffect,useRef,useState}from"react";
import{supabase}from"./main";
import{createMediaCall}from"./webrtc";

const features=[["01","Private by design","Profiles, invitations and rooms are built around user-controlled privacy."],["02","Real connections","Discover people, build connections and move into private conversations when invited."],["03","Trust first","Verification, reporting, blocking and moderation belong in the foundation."]];
const baseNav=["Home","Discover","Connections","Messages","Rooms","Notifications","Calls","Subscription","Profile","Safety","Account Settings"];
const premiumNav=["My Room","Room Settings","Invitations","Profile Analytics"];

export default function App(){
 const[session,setSession]=useState(null),[profile,setProfile]=useState(null),[isAdmin,setIsAdmin]=useState(false),[mfaRequired,setMfaRequired]=useState(false),[mode,setMode]=useState(null),[demoMode,setDemoMode]=useState(false),[email,setEmail]=useState(""),[password,setPassword]=useState(""),[name,setName]=useState(""),[dob,setDob]=useState(""),[ageConfirmed,setAgeConfirmed]=useState(false),[terms,setTerms]=useState(false),[busy,setBusy]=useState(false),[message,setMessage]=useState(""),[active,setActive]=useState("Home"),[mobileOpen,setMobileOpen]=useState(false),[recovery,setRecovery]=useState(false);
 useEffect(()=>{supabase.auth.getSession().then(({data})=>setSession(data.session));const{data}=supabase.auth.onAuthStateChange((event,s)=>{if(event==="PASSWORD_RECOVERY")setRecovery(true);setSession(s)});return()=>data.subscription.unsubscribe()},[]);
 useEffect(()=>{if(!session){setMfaRequired(false);return}supabase.auth.mfa.getAuthenticatorAssuranceLevel().then(({data})=>setMfaRequired(data?.nextLevel==="aal2"&&data?.currentLevel!=="aal2")).catch(()=>setMfaRequired(false))},[session]); useEffect(()=>{if(!session){setProfile(null);setIsAdmin(false);return}supabase.rpc("is_current_user_admin").then(({data})=>setIsAdmin(data===true));let cancelled=false;const loadProfile=async()=>{const[{data,error},{data:isAdminData}]=await Promise.all([supabase.from("profiles").select("display_name,role,status,verification_status,avatar_url").eq("id",session.user.id).maybeSingle(),supabase.rpc("is_current_user_admin")]);if(cancelled)return;setIsAdmin(isAdminData===true);if(error){setProfile(null);return}if(!data){setProfile(null);return}if(data.status!=="active"){setProfile(null);await supabase.auth.signOut({scope:"global"});setMessage(data.status==="deleted"?"This AMORA account has been deleted.":"This AMORA account is not currently active.");return}setProfile(data)};loadProfile();const channel=supabase.channel("amora-account-status-"+session.user.id).on("postgres_changes",{event:"UPDATE",schema:"public",table:"profiles",filter:"id=eq."+session.user.id},async payload=>{if(payload.new?.status!=="active"){setProfile(null);await supabase.auth.signOut({scope:"global"});setMessage(payload.new?.status==="deleted"?"This AMORA account has been deleted.":"This AMORA account is not currently active.");}else{setProfile(payload.new)}}).subscribe();const onFocus=()=>loadProfile();window.addEventListener("focus",onFocus);return()=>{cancelled=true;window.removeEventListener("focus",onFocus);supabase.removeChannel(channel)}},[session]);
 const submit=async e=>{e.preventDefault();setBusy(true);setMessage("");
  if(mode==="signup"){if(!ageConfirmed||!terms){setMessage("You must confirm that you are 18+ and accept AMORA's terms and privacy requirements.");setBusy(false);return}
   const{error}=await supabase.auth.signUp({email,password,options:{data:{display_name:name,date_of_birth:dob,is_age_confirmed:true,terms_accepted:true,privacy_accepted:true,terms_version:"1.0",privacy_version:"1.0",community_rules_version:"1.0",age_safety_version:"1.0"}}});
   setMessage(error?error.message:"Account created. Check your email to verify your address before signing in.");if(!error)setMode("signin");
  }else{const{data,error}=await supabase.auth.signInWithPassword({email,password});if(error){setMessage(error.message)}else if(data.user&&!data.user.email_confirmed_at){await supabase.auth.signOut({scope:"global"});setMessage("Please verify your email address before using AMORA.")}else setMessage("Signed in.");}
  setBusy(false)
 };
 const signout=async()=>{const{error}=await supabase.auth.signOut();setMessage(error?.message||"Signed out.");if(!error)setActive("Home")};
 if(recovery)return <PasswordRecovery onDone={()=>setRecovery(false)}/>;
 if(demoMode)return <AppShell session={{user:{id:"demo-user",email:"demo@amora.example"}}} profile={{display_name:"AMORA Demo",role:"premium",verification_status:"amora_verified"}} isAdmin={false} active={active} setActive={setActive} signout={()=>{setDemoMode(false);setActive("Home")}} mobileOpen={mobileOpen} setMobileOpen={setMobileOpen} demoMode/>;
 if(session&&mfaRequired)return <MFAChallenge onVerified={()=>setMfaRequired(false)}/>;if(session)return <AppShell session={session} profile={profile} isAdmin={isAdmin} active={active} setActive={setActive} signout={signout} mobileOpen={mobileOpen} setMobileOpen={setMobileOpen}/>;
 return <Landing mode={mode} setMode={setMode} demo={setDemoMode} email={email} setEmail={setEmail} password={password} setPassword={setPassword} name={name} setName={setName} dob={dob} setDob={setDob} ageConfirmed={ageConfirmed} setAgeConfirmed={setAgeConfirmed} terms={terms} setTerms={setTerms} busy={busy} message={message} setMessage={setMessage} submit={submit}/>;
}

function AppShell({session,profile,isAdmin,active,setActive,signout,mobileOpen,setMobileOpen,demoMode=false}){
 const isPremium=profile?.role==="premium";
 const nav=isAdmin?[...baseNav,...premiumNav,"Admin"]:isPremium?[...baseNav,...premiumNav]:baseNav;
 const initials=(profile?.display_name||session.user.email||"A").slice(0,1).toUpperCase();
 return <div className="app-shell">
  <aside className={mobileOpen?"sidebar open":"sidebar"}><div className="side-top"><a className="brand" href="/"><b className="brand-mark"><img src="/amora-mark.svg" alt="" /></b><span>AMORA</span></a><button className="mobile-close" onClick={()=>setMobileOpen(false)}>×</button></div>
   <div className="account-mini"><span className="avatar">{profile?.avatar_url?<img src={profile.avatar_url} alt="" />:initials}</span><div><strong>{profile?.display_name||"AMORA member"}</strong><small>{isPremium?"Premium":"Member"}</small></div></div>
   <nav className="app-nav">{nav.map(item=><button key={item} className={active===item?"active":""} onClick={()=>{setActive(item);setMobileOpen(false)}}><span className="nav-dot"/>{item}{["Notifications","Messages"].includes(item)&&!demoMode&&<span className="nav-count">{item==="Notifications"?<NotificationCount session={session}/>:item==="Messages"?<MessageCount session={session}/>:null}</span>}</button>)}</nav>
   <button className="signout" onClick={signout}>Sign out</button>
  </aside>
  <div className="app-main"><header className="app-header"><button className="menu-button" onClick={()=>setMobileOpen(true)}>☰</button><div><small>AMORA / {active.toUpperCase()}</small><h1>{active}</h1></div><div className="header-actions"><button aria-label="Notifications" onClick={()=>setActive("Notifications")}>♡</button><span className="avatar">{profile?.avatar_url?<img src={profile.avatar_url} alt="" />:initials}</span></div></header>
   <main className="app-content"><Screen active={active} profile={profile} session={session} isPremium={isPremium} isAdmin={isAdmin} demoMode={demoMode}/></main>
  </div>
 </div>
}

function Discover({session,isPremium}){const[people,setPeople]=useState([]),[links,setLinks]=useState([]),[search,setSearch]=useState(""),[age,setAge]=useState("all"),[verified,setVerified]=useState(false),[online,setOnline]=useState(false),[busy,setBusy]=useState(true),[notice,setNotice]=useState("");useEffect(()=>{let live=true;(async()=>{setBusy(true);const[{data:p},{data:c}]=await Promise.all([supabase.from("discoverable_profiles").select("id,display_name,age,bio,country_code,city,interests,languages,avatar_url,role,show_online_status,allow_messages,allow_calls,allow_invitations,verification_status,last_seen_at").neq("id",session.user.id).order("last_seen_at",{ascending:false,nullsLast:true}).limit(60),supabase.from("connections").select("requester_id,addressee_id,status").or("requester_id.eq."+session.user.id+",addressee_id.eq."+session.user.id)]);if(live){setPeople(p||[]);setLinks(c||[]);setBusy(false)}})();return()=>{live=false}},[session.user.id]);const isOnline=p=>p.show_online_status&&p.last_seen_at&&(Date.now()-new Date(p.last_seen_at).getTime()<5*60*1000);const stateFor=id=>{const x=links.find(v=>(v.requester_id===session.user.id&&v.addressee_id===id)||(v.addressee_id===session.user.id&&v.requester_id===id));return x?.status||null};const connect=async p=>{setNotice("");if(stateFor(p.id)){setNotice("A connection already exists for this profile.");return}const{error}=await supabase.from("connections").insert({requester_id:session.user.id,addressee_id:p.id,status:"pending"});if(error)setNotice(error.message);else{setLinks(v=>[...v,{requester_id:session.user.id,addressee_id:p.id,status:"pending"}]);setNotice("Connection request sent.")}};const invite=async p=>{setNotice("");const{data:room,error:roomError}=await supabase.from("rooms").select("id,status").eq("owner_id",session.user.id).maybeSingle();if(roomError||!room){setNotice("Create your private room before sending invitations.");return}if(room.status!=="active"){setNotice("Your room is not active.");return}const{error}=await supabase.from("room_invitations").insert({room_id:room.id,inviter_id:session.user.id,invitee_id:p.id,status:"pending"});setNotice(error?error.message:"Room invitation sent.")};const filtered=people.filter(p=>{const q=search.trim().toLowerCase();const text=[p.display_name,p.bio,p.city,p.country_code,...(p.interests||[]),...(p.languages||[])].filter(Boolean).join(" ").toLowerCase();const ageOk=age==="all"||(age==="18-24"&&p.age>=18&&p.age<=24)||(age==="25-34"&&p.age>=25&&p.age<=34)||(age==="35-44"&&p.age>=35&&p.age<=44)||(age==="45+"&&p.age>=45);return(!q||text.includes(q))&&ageOk&&(!verified||["identity_verified","amora_verified"].includes(p.verification_status))&&(!online||isOnline(p))});return <div className="discover"><div className="discover-tools"><input placeholder="Search people, interests or city" value={search} onChange={e=>setSearch(e.target.value)}/><select value={age} onChange={e=>setAge(e.target.value)}><option value="all">Any age</option><option value="18-24">18–24</option><option value="25-34">25–34</option><option value="35-44">35–44</option><option value="45+">45+</option></select><label className="filter-check"><input type="checkbox" checked={verified} onChange={e=>setVerified(e.target.checked)}/> Verified</label><label className="filter-check"><input type="checkbox" checked={online} onChange={e=>setOnline(e.target.checked)}/> Online now</label></div>{notice&&<div className="discover-notice">{notice}<button onClick={()=>setNotice("")}>×</button></div>}{busy?<div className="empty-panel"><h3>Loading discoverable profiles…</h3><p>AMORA is checking your privacy rules and connection state.</p></div>:filtered.length===0?<div className="empty-panel"><div className="empty-icon">A</div><h3>No profiles match these filters yet.</h3><p>That is expected while the AMORA community is being built. Your discovery system is connected and ready for real profiles.</p></div>:<div className="profile-grid">{filtered.map(p=>{const state=stateFor(p.id);return <article className="profile-card" key={p.id}><div className="profile-cover">{p.avatar_url?<img src={p.avatar_url} alt="" />:<span>{(p.display_name||"A").slice(0,1).toUpperCase()}</span>}<i className={isOnline(p)?"online":""}>{isOnline(p)?"Online":"Available"}</i></div><div className="profile-body"><div className="profile-name"><h3>{p.display_name||"AMORA member"}, {p.age}</h3>{["identity_verified","amora_verified"].includes(p.verification_status)&&<b>✓ Verified</b>}</div><p>{[p.city,p.country_code].filter(Boolean).join(", ")||"Location private"}</p><p className="profile-bio">{p.bio||"Open to meaningful connections."}</p>{(p.interests||[]).slice(0,4).map(x=><span className="tag" key={x}>{x}</span>)}<div className="profile-actions"><button className="primary" disabled={!!state} onClick={()=>connect(p)}>{state==="pending"?"Requested":state==="accepted"?"Connected":"Connect"}</button><button className="ghost" disabled={!p.allow_messages}>Message</button>{isPremium&&p.allow_invitations&&<button className="ghost" onClick={()=>invite(p)}>Invite to room</button>}<button className="ghost" onClick={async()=>{const description=window.prompt("Briefly describe the issue with this profile.");if(!description?.trim())return;const{error}=await supabase.from("reports").insert({reporter_id:session.user.id,reported_user_id:p.id,category:"profile_safety",description:description.trim()});setNotice(error?.message||"Profile report submitted to AMORA safety review.")}}>Report</button><button className="ghost" onClick={async()=>{if(!window.confirm("Block this member? You will no longer see or interact with this profile through AMORA."))return;const{error}=await supabase.from("blocks").insert({blocker_id:session.user.id,blocked_id:p.id});setNotice(error?.message||"Member blocked.");if(!error)setPeople(v=>v.filter(x=>x.id!==p.id))}}>Block</button></div></div></article>})}</div>}</div>}

function Connections({session}){const[items,setItems]=useState([]),[busy,setBusy]=useState(true),[notice,setNotice]=useState("");const load=async()=>{setBusy(true);const{data,error}=await supabase.from("connections").select("id,requester_id,addressee_id,status,created_at,updated_at").or("requester_id.eq."+session.user.id+",addressee_id.eq."+session.user.id).order("updated_at",{ascending:false});if(error)setNotice(error.message);else{const ids=[...(data||[])].map(x=>x.requester_id===session.user.id?x.addressee_id:x.requester_id);let profiles=[];let blockedIds=[];if(ids.length){const[r,b]=await Promise.all([supabase.from("profiles").select("id,display_name,avatar_url,city,country_code,verification_status,last_seen_at,show_online_status,bio").in("id",ids),supabase.from("blocks").select("blocker_id,blocked_id").or("blocker_id.eq."+session.user.id+",blocked_id.eq."+session.user.id)]);profiles=r.data||[];blockedIds=(b.data||[]).map(x=>x.blocker_id===session.user.id?x.blocked_id:x.blocker_id)}setItems((data||[]).filter(x=>!blockedIds.includes(x.requester_id===session.user.id?x.addressee_id:x.requester_id)).map(x=>({...x,person:profiles.find(p=>p.id===(x.requester_id===session.user.id?x.addressee_id:x.requester_id))})));}setBusy(false)};useEffect(()=>{load()},[session.user.id]);const respond=async(id,status)=>{setNotice("");const{error}=await supabase.from("connections").update({status}).eq("id",id);if(error)setNotice(error.message);else load()};const remove=async id=>{const{error}=await supabase.from("connections").update({status:"removed"}).eq("id",id);if(error)setNotice(error.message);else load()};const online=p=>p?.show_online_status&&p.last_seen_at&&(Date.now()-new Date(p.last_seen_at).getTime()<300000);return <div className="connections"><div className="connection-tabs"><span>{items.filter(x=>x.status==="pending"&&x.addressee_id===session.user.id).length} incoming</span><span>{items.filter(x=>x.status==="pending"&&x.requester_id===session.user.id).length} sent</span><span>{items.filter(x=>x.status==="accepted").length} connected</span></div>{notice&&<div className="discover-notice">{notice}</div>}{busy?<div className="empty-panel"><h3>Loading connections…</h3><p>AMORA is loading your connection requests.</p></div>:items.filter(x=>["pending","accepted"].includes(x.status)).length===0?<div className="empty-panel"><div className="empty-icon">A</div><h3>Your connections will appear here.</h3><p>Send a request from Discover and manage it here. No connection is created without an explicit action.</p></div>:<div className="connection-list">{items.filter(x=>["pending","accepted"].includes(x.status)).map(x=>{const p=x.person||{};const incoming=x.status==="pending"&&x.addressee_id===session.user.id;return <article className="connection-row" key={x.id}><div className="connection-avatar">{p.avatar_url?<img src={p.avatar_url} alt=""/>:<span>{(p.display_name||"A").slice(0,1).toUpperCase()}</span>}</div><div className="connection-info"><div><h3>{p.display_name||"AMORA member"} {["identity_verified","amora_verified"].includes(p.verification_status)&&<b>✓</b>}</h3><small>{online(p)?"Online":([p.city,p.country_code].filter(Boolean).join(", ")||"Location private")}</small></div><p>{p.bio||"AMORA member"}</p></div><div className="connection-actions">{x.status==="accepted"?<><span className="accepted-label">Connected</span><button className="ghost" onClick={()=>remove(x.id)}>Remove</button></>:incoming?<><button className="primary" onClick={()=>respond(x.id,"accepted")}>Accept</button><button className="ghost" onClick={()=>respond(x.id,"removed")}>Decline</button></>:<><span className="pending-label">Request sent</span><button className="ghost" onClick={()=>remove(x.id)}>Cancel</button></>}</div></article>})}</div>}</div>}

function NotificationCount({session}){const[n,setN]=useState(0);useEffect(()=>{let live=true;supabase.from("notifications").select("id",{count:"exact",head:true}).eq("user_id",session.user.id).is("read_at",null).then(({count})=>{if(live)setN(count||0)});return()=>{live=false}},[session.user.id]);return n>0?n:null}
function MessageCount({session}){const[n,setN]=useState(0);useEffect(()=>{let live=true;supabase.from("notifications").select("id",{count:"exact",head:true}).eq("user_id",session.user.id).eq("type","message").is("read_at",null).then(({count})=>{if(live)setN(count||0)});return()=>{live=false}},[session.user.id]);return n>0?n:null}

function Messages({session}){const[conversations,setConversations]=useState([]),[selected,setSelected]=useState(null),[messages,setMessages]=useState([]),[connections,setConnections]=useState([]),[busy,setBusy]=useState(true),[sending,setSending]=useState(false),[draft,setDraft]=useState(""),[notice,setNotice]=useState("");
 const load=async()=>{setBusy(true);const{data,error}=await supabase.from("conversation_members").select("conversation_id,user_id,joined_at,last_read_at,conversations(id,updated_at,conversation_members(user_id),messages(id,body,sender_id,created_at))").eq("user_id",session.user.id);if(error){setNotice(error.message);setBusy(false);return}const rows=(data||[]).map(x=>x.conversations).filter(Boolean).map(c=>({...c,otherId:(c.conversation_members||[]).map(m=>m.user_id).find(id=>id!==session.user.id)}));const ids=rows.map(x=>x.otherId).filter(Boolean);let profiles=[];if(ids.length){const r=await supabase.from("profiles").select("id,display_name,avatar_url,verification_status,last_seen_at,show_online_status,bio").in("id",ids);profiles=r.data||[]}setConversations(rows.map(x=>({...x,person:profiles.find(p=>p.id===x.otherId)})));const r=await supabase.from("connections").select("requester_id,addressee_id,status").eq("status","accepted").or("requester_id.eq."+session.user.id+",addressee_id.eq."+session.user.id);if(!r.error)setConnections(r.data||[]);setBusy(false)};
 useEffect(()=>{load()},[session.user.id]);
 useEffect(()=>{if(!selected)return;const loadMessages=async()=>{const{data,error}=await supabase.from("messages").select("id,body,sender_id,created_at,message_type,deleted_at").eq("conversation_id",selected.id).order("created_at",{ascending:true}).limit(200);if(error)setNotice(error.message);else setMessages(data||[])};loadMessages();const channel=supabase.channel("messages-"+selected.id).on("postgres_changes",{event:"INSERT",schema:"public",table:"messages",filter:"conversation_id=eq."+selected.id},payload=>setMessages(v=>v.some(m=>m.id===payload.new.id)?v:[...v,payload.new])).subscribe();return()=>{supabase.removeChannel(channel)}},[selected?.id]);
 const start=async id=>{setNotice("");const{data,error}=await supabase.rpc("get_or_create_direct_conversation",{target_user:id});if(error){setNotice(error.message);return}await load();setTimeout(()=>setSelected(v=>v||{id:data,otherId:id}),0)};
 const send=async e=>{e.preventDefault();const body=draft.trim();if(!body||!selected)return;setSending(true);setNotice("");const{error}=await supabase.from("messages").insert({conversation_id:selected.id,sender_id:session.user.id,body,message_type:"text"});if(error)setNotice(error.message);else setDraft("");setSending(false)};
 const people=connections.map(c=>c.requester_id===session.user.id?c.addressee_id:c.requester_id).filter(id=>!conversations.some(x=>x.otherId===id));
 const selectedPerson=selected?.person||conversations.find(x=>x.id===selected?.id)?.person||null;
 return <div className="messages-layout"><section className="conversation-panel"><div className="messages-heading"><div><small>PRIVATE MESSAGES</small><h3>Conversations</h3></div></div>{notice&&<div className="discover-notice">{notice}</div>}{people.length>0&&<div className="new-conversation"><strong>Start a conversation</strong>{people.map(id=><button key={id} onClick={()=>start(id)}>Message connection</button>)}</div>}{busy?<div className="empty-panel compact"><h3>Loading messages…</h3><p>Your private conversations are being loaded.</p></div>:conversations.length===0?<div className="empty-panel compact"><div className="empty-icon">A</div><h3>No conversations yet.</h3><p>Connect with someone first, then start a private conversation here.</p></div>:<div className="conversation-list">{conversations.map(c=><button key={c.id} className={selected?.id===c.id?"conversation-item selected":"conversation-item"} onClick={()=>setSelected(c)}><span className="avatar">{(c.person?.display_name||"A").slice(0,1).toUpperCase()}</span><span><strong>{c.person?.display_name||"AMORA member"}</strong><small>{(c.messages||[]).slice(-1)[0]?.body||"Start a private conversation"}</small></span></button>)}</div>}</section><section className="chat-panel">{!selected?<div className="empty-panel chat-empty"><div className="empty-icon">A</div><h3>Select a conversation</h3><p>Your messages stay inside the connection and privacy boundaries defined by AMORA.</p></div>:<><header className="chat-header"><span className="avatar">{(selectedPerson?.display_name||"A").slice(0,1).toUpperCase()}</span><div><strong>{selectedPerson?.display_name||"AMORA member"}</strong><small>{selectedPerson?.show_online_status&&selectedPerson?.last_seen_at&&Date.now()-new Date(selectedPerson.last_seen_at).getTime()<300000?"Online":"Private conversation"}</small></div><span className="chat-safety-actions"><button className="ghost" onClick={async()=>{const description=window.prompt("Briefly describe the issue with this conversation.");if(!description?.trim())return;const{error}=await supabase.from("reports").insert({reporter_id:session.user.id,reported_user_id:selected.otherId,category:"message_safety",description:description.trim()});setNotice(error?.message||"Report submitted to AMORA safety review.")}}>Report</button><button className="ghost" onClick={async()=>{if(!window.confirm("Block this member? You will no longer be able to interact with them through AMORA."))return;const{error}=await supabase.from("blocks").insert({blocker_id:session.user.id,blocked_id:selected.otherId});setNotice(error?.message||"Member blocked.");if(!error){setSelected(null);load()}}}>Block</button></span></header><div className="chat-messages">{messages.map(m=><div key={m.id} className={m.sender_id===session.user.id?"bubble mine":"bubble"}>{m.deleted_at?"Message deleted":m.body}<small>{new Date(m.created_at).toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})}</small></div>)}</div><form className="chat-compose" onSubmit={send}><input value={draft} onChange={e=>setDraft(e.target.value)} placeholder="Write a private message…" maxLength={5000}/><button className="primary" disabled={sending||!draft.trim()}>{sending?"Sending…":"Send"}</button></form></>}</section></div>}

function Notifications({session}){const[items,setItems]=useState([]),[busy,setBusy]=useState(true),[notice,setNotice]=useState("");const load=async()=>{setBusy(true);const{data,error}=await supabase.from("notifications").select("id,type,title,body,actor_id,entity_type,entity_id,read_at,created_at").eq("user_id",session.user.id).order("created_at",{ascending:false}).limit(100);if(error)setNotice(error.message);else setItems(data||[]);setBusy(false)};useEffect(()=>{load();const channel=supabase.channel("notifications-"+session.user.id).on("postgres_changes",{event:"INSERT",schema:"public",table:"notifications",filter:"user_id=eq."+session.user.id},payload=>setItems(v=>[payload.new,...v])).subscribe();return()=>{supabase.removeChannel(channel)}},[session.user.id]);const mark=async id=>{const{error}=await supabase.from("notifications").update({read_at:new Date().toISOString()}).eq("id",id);if(error)setNotice(error.message);else setItems(v=>v.map(x=>x.id===id?{...x,read_at:new Date().toISOString()}:x))};const all=async()=>{const{error}=await supabase.from("notifications").update({read_at:new Date().toISOString()}).eq("user_id",session.user.id).is("read_at",null);if(error)setNotice(error.message);else load()};return <div className="notifications-page"><div className="notification-toolbar"><div><small>YOUR UPDATES</small><h3>Notifications</h3></div><button className="ghost" onClick={all}>Mark all as read</button></div>{notice&&<div className="discover-notice">{notice}</div>}{busy?<div className="empty-panel"><h3>Loading notifications…</h3><p>AMORA is checking your latest account activity.</p></div>:items.length===0?<div className="empty-panel"><div className="empty-icon">A</div><h3>You're all caught up.</h3><p>Connection requests, messages, invitations and security events will appear here.</p></div>:<div className="notification-list">{items.map(n=><button key={n.id} className={n.read_at?"notification-row":"notification-row unread"} onClick={()=>!n.read_at&&mark(n.id)}><span className="notification-icon">{n.type==="message"?"M":n.type==="connection_request"?"C":n.type==="connection_accepted"?"✓":"A"}</span><span><strong>{n.title}</strong><small>{n.body}</small><em>{new Date(n.created_at).toLocaleString()}</em></span></button>)}</div>}</div>}


function Subscription({session,profile}){const[items,setItems]=useState([]),[plans,setPlans]=useState([]),[busy,setBusy]=useState(true),[notice,setNotice]=useState("");useEffect(()=>{(async()=>{setBusy(true);const[a,b]=await Promise.all([supabase.from("subscriptions").select("id,subscription_type,status,currency,amount_minor,current_period_start,current_period_end,cancel_at_period_end").eq("user_id",session.user.id).order("created_at",{ascending:false}),supabase.from("subscription_plans").select("id,slug,name,audience,currency,amount_minor,interval").eq("active",true).order("audience")]);if(a.error||b.error)setNotice((a.error||b.error).message);setItems(a.data||[]);setPlans(b.data||[]);setBusy(false)})()},[session.user.id]);return <div className="subscription-page">{notice&&<div className="discover-notice">{notice}</div>}{busy?<div className="empty-panel"><h3>Loading subscription status…</h3></div>:<><div className="subscription-hero"><span className="room-badge">AMORA MEMBERSHIP</span><h2>{profile?.role==="premium"?"Premium member":"Regular member"}</h2><p>Subscriptions are the foundation for room access and platform membership. Payment checkout is deliberately not enabled until AMORA's pricing and payment provider are configured.</p></div><div className="subscription-grid">{items.length===0?<div className="empty-panel"><h3>No active subscription</h3><p>Your account has no subscription record yet.</p></div>:items.map(x=><article className="subscription-card" key={x.id}><span className="room-badge">{x.subscription_type}</span><h3>{x.status}</h3><p>{x.currency} {(x.amount_minor/100).toFixed(2)} · {x.current_period_end?"Ends "+new Date(x.current_period_end).toLocaleDateString():"Period not set"}</p>{x.cancel_at_period_end?<><small>Cancellation is scheduled for the end of this billing period.</small><button className="ghost" onClick={async()=>{const{error}=await supabase.rpc("resume_own_subscription",{p_subscription_id:x.id});setNotice(error?.message||"Subscription cancellation reversed.");if(!error){const{data}=await supabase.from("subscriptions").select("id,subscription_type,status,currency,amount_minor,current_period_start,current_period_end,cancel_at_period_end").eq("user_id",session.user.id).order("created_at",{ascending:false});setItems(data||[])}}}>Resume subscription</button></>:["trialing","active","past_due","paused"].includes(x.status)&&<button className="ghost" onClick={async()=>{if(!window.confirm("Cancel this subscription at the end of the current billing period?"))return;const{error}=await supabase.rpc("cancel_own_subscription",{p_subscription_id:x.id});setNotice(error?.message||"Subscription cancellation scheduled.");if(!error){const{data}=await supabase.from("subscriptions").select("id,subscription_type,status,currency,amount_minor,current_period_start,current_period_end,cancel_at_period_end").eq("user_id",session.user.id).order("created_at",{ascending:false});setItems(data||[])}}}>Cancel at period end</button>}</article>)}{plans.length>0&&plans.map(p=><article className="subscription-card" key={p.id}><span className="room-badge">{p.audience.toUpperCase()}</span><h3>{p.name}</h3><p>{p.currency} {(p.amount_minor/100).toFixed(2)} / {p.interval}</p><button className="ghost" disabled>Checkout coming after pricing setup</button></article>)}</div></>}</div>}

function Rooms({session,isPremium}){const[room,setRoom]=useState(null),[invited,setInvited]=useState([]),[busy,setBusy]=useState(true),[notice,setNotice]=useState("");const load=async()=>{setBusy(true);setNotice("");const r=await supabase.from("rooms").select("id,owner_id,name,description,status,chat_enabled,voice_enabled,video_enabled,requires_invitation,requires_subscription,updated_at").eq("owner_id",session.user.id).maybeSingle();if(r.error){setNotice(r.error.message)}else setRoom(r.data||null);if(!isPremium){const i=await supabase.from("room_invitations").select("id,room_id,inviter_id,invitee_id,status,expires_at,created_at,rooms(id,name,description,status,chat_enabled,voice_enabled,video_enabled,requires_subscription)").eq("invitee_id",session.user.id).eq("status","accepted").order("created_at",{ascending:false});if(!i.error)setInvited(i.data||[])}setBusy(false)};useEffect(()=>{load()},[session.user.id,isPremium]);const create=async()=>{const{data,error}=await supabase.from("rooms").insert({owner_id:session.user.id,name:"Private Room",description:"A private space for invited AMORA members.",status:"active",chat_enabled:true,voice_enabled:true,video_enabled:true,requires_invitation:true,requires_subscription:true}).select().single();if(error)setNotice(error.message);else setRoom(data)};return <div className="room-page">{notice&&<div className="discover-notice">{notice}</div>}{busy?<div className="empty-panel"><h3>Loading rooms…</h3><p>AMORA is checking your room access.</p></div>:isPremium?<>{!room?<div className="empty-panel"><div className="empty-icon">A</div><h3>Your private room is ready to create.</h3><p>Premium members can create one private room. Invitations and room controls will use this room.</p><button className="primary" onClick={create}>Create my room</button></div>:<RoomCard room={room} owner session={session}/>}</>:invited.length===0?<div className="empty-panel"><div className="empty-icon">A</div><h3>No rooms yet.</h3><p>Accepted private-room invitations will appear here.</p></div>:<div className="room-grid">{invited.map(x=><RoomCard key={x.id} room={x.rooms} invitation={x} session={session}/>)}</div>}</div>}

function RoomCard({room,owner,invitation,session}){const[open,setOpen]=useState(false);if(!room)return null;return <article className="room-card"><div className="room-card-top"><span className="room-badge">PRIVATE ROOM</span><span className={room.status==="active"?"room-live":"room-offline"}>● {room.status}</span></div><h3>{room.name}</h3><p>{room.description||"A private AMORA space."}</p><div className="room-capabilities"><span>Chat {room.chat_enabled?"on":"off"}</span><span>Voice {room.voice_enabled?"on":"off"}</span><span>Video {room.video_enabled?"on":"off"}</span></div>{owner?<small>Only invited members with active access can enter.</small>:<small>Invitation accepted · Active subscription required.</small>}<div className="room-actions"><button className="primary" onClick={()=>setOpen(true)}>{owner?"Open room":"Enter room"}</button></div>{open&&<RoomInterface room={room} session={session} onClose={()=>setOpen(false)}/>}</article>}

function RoomInterface({room,session,onClose}){const[messages,setMessages]=useState([]),[body,setBody]=useState(""),[busy,setBusy]=useState(true),[sending,setSending]=useState(false),[notice,setNotice]=useState(""),[obscured,setObscured]=useState(false);const userName=session.user.user_metadata?.display_name||"AMORA member";const [sessionStamp]=useState(()=>new Date().toLocaleString());const [protectionNotice,setProtectionNotice]=useState("");useEffect(()=>{let channel;let mounted=true;(async()=>{const{data,error}=await supabase.from("room_messages").select("id,sender_id,body,created_at").eq("room_id",room.id).order("created_at",{ascending:true}).limit(100);if(mounted){setMessages(data||[]);if(error)setNotice(error.message);setBusy(false)}channel=supabase.channel("room-chat-"+room.id).on("postgres_changes",{event:"INSERT",schema:"public",table:"room_messages",filter:"room_id=eq."+room.id},payload=>setMessages(v=>v.some(x=>x.id===payload.new.id)?v:[...v,payload.new])).subscribe()})();return()=>{mounted=false;if(channel)supabase.removeChannel(channel)}},[room.id]);useEffect(()=>{const block=e=>{if(e.key==="PrintScreen"||(e.ctrlKey&&(e.key.toLowerCase()==="s"||e.key.toLowerCase()==="p"))){e.preventDefault();setNotice("AMORA rooms are protected. Downloading or printing room content is disabled.")}};const menu=e=>e.preventDefault();const copy=e=>e.preventDefault();const drag=e=>e.preventDefault();const beforePrint=()=>setNotice("AMORA rooms cannot be printed.");window.addEventListener("keydown",block);window.addEventListener("beforeprint",beforePrint);const visibility=()=>{const hidden=document.visibilityState!=="visible";setObscured(hidden);if(hidden)setProtectionNotice("Room content hidden while AMORA is not visible.");else setProtectionNotice("")};document.addEventListener("visibilitychange",visibility);const root=document.querySelector(".room-interface");root?.addEventListener("contextmenu",menu);root?.addEventListener("copy",copy);root?.addEventListener("cut",copy);root?.addEventListener("dragstart",drag);return()=>{window.removeEventListener("keydown",block);window.removeEventListener("beforeprint",beforePrint);document.removeEventListener("visibilitychange",visibility);root?.removeEventListener("contextmenu",menu);root?.removeEventListener("copy",copy);root?.removeEventListener("cut",copy);root?.removeEventListener("dragstart",drag)}},[]);const send=async()=>{const text=body.trim();if(!text||sending)return;setSending(true);const{error}=await supabase.from("room_messages").insert({room_id:room.id,sender_id:(await supabase.auth.getUser()).data.user?.id,body:text});if(error)setNotice(error.message);else setBody("");setSending(false)};return <div className="room-overlay"><div className={"room-interface room-protected"+(obscured?" room-capture-obscured":"")}><div className="room-privacy-watermark"><span>{userName}</span><span>AMORA PRIVATE ROOM</span><span>{sessionStamp}</span></div><div className="room-interface-head"><div><span className="room-badge">PRIVATE ROOM · PROTECTED</span><h3>{room.name}</h3></div><button className="ghost" onClick={onClose}>Close</button></div><div className="room-privacy-notice">Private room content is protected against casual downloading, printing and copying. Screen capture cannot be completely prevented by a web browser.</div>{protectionNotice&&<div className="room-protection-alert">{protectionNotice}</div>}{notice&&<div className="discover-notice">{notice}</div>}<div className="room-chat">{busy?<p>Loading chat…</p>:messages.length===0?<p>No messages yet. Start the conversation.</p>:messages.map(m=><div className="room-message" key={m.id}><small>{m.sender_id===session.user.id?"You":"Member"} · {new Date(m.created_at).toLocaleString()}</small><div>{m.body}</div></div>)}</div>{room.chat_enabled?<div className="room-composer"><input value={body} maxLength={4000} placeholder="Write a message…" onChange={e=>setBody(e.target.value)} onKeyDown={e=>e.key==="Enter"&&send()}/><button className="primary" disabled={sending||!body.trim()} onClick={send}>{sending?"Sending…":"Send"}</button></div>:<p className="setting-note">Chat is disabled for this room.</p>}<div className="room-capabilities"><span>Voice {room.voice_enabled?"available":"off"}</span><span>Video {room.video_enabled?"available":"off"}</span></div><RoomCallActions room={room} session={session}/></div></div>}

function RoomCallActions({room,session}){const[people,setPeople]=useState([]),[presence,setPresence]=useState([]),[pending,setPending]=useState([]),[search,setSearch]=useState(""),[notice,setNotice]=useState(""),[busy,setBusy]=useState(true),[inviting,setInviting]=useState(null),[revoking,setRevoking]=useState(null);const load=async()=>{const{data:errorData}=await supabase.from("room_invitations").select("invitee_id,status,expires_at").eq("room_id",room.id);const invitations=errorData||[];setPending(invitations.filter(x=>x.status==="pending"));const ids=[room.owner_id,...invitations.filter(x=>x.status==="accepted").map(x=>x.invitee_id)].filter(id=>id!==session.user.id);if(ids.length){const p=await supabase.from("profiles").select("id,display_name,allow_calls").in("id",ids);setPeople(p.data||[])}else setPeople([]);const{data:pres}=await supabase.from("room_presence").select("user_id,last_seen_at").eq("room_id",room.id);setPresence(pres||[])};useEffect(()=>{let channel;(async()=>{await load();await supabase.from("room_presence").upsert({room_id:room.id,user_id:session.user.id,last_seen_at:new Date().toISOString()});channel=supabase.channel("room-presence-"+room.id).on("postgres_changes",{event:"*",schema:"public",table:"room_presence",filter:"room_id=eq."+room.id},load).subscribe();setBusy(false)})();return()=>{if(channel)supabase.removeChannel(channel);supabase.from("room_presence").delete().eq("room_id",room.id).eq("user_id",session.user.id)}},[room.id,session.user.id]);const invite=async id=>{setInviting(id);const expires=new Date(Date.now()+7*24*60*60*1000).toISOString();const{error}=await supabase.from("room_invitations").insert({room_id:room.id,inviter_id:session.user.id,invitee_id:id,status:"pending",expires_at:expires});setNotice(error?.message||"Invitation sent.");if(!error){setSearch("");await load()}setInviting(null)};const revoke=async id=>{setRevoking(id);const{error}=await supabase.from("room_invitations").update({status:"revoked"}).eq("room_id",room.id).eq("invitee_id",id).eq("status","pending");setNotice(error?.message||"Invitation revoked.");if(!error)await load();setRevoking(null)};const call=async(id,type)=>{const{error}=await supabase.rpc("start_room_call",{p_room_id:room.id,p_callee:id,p_call_type:type});if(error)setNotice(error.message);else setNotice("Call started. Open Calls to manage the connection.")};const report=async(id)=>{const description=window.prompt("Briefly describe the issue in this room.");if(!description?.trim())return;const{error}=await supabase.from("reports").insert({reporter_id:session.user.id,reported_user_id:id,room_id:room.id,category:"room_safety",description:description.trim()});setNotice(error?.message||"Report submitted to AMORA safety review.")};const block=async(id)=>{if(!window.confirm("Block this member? They will no longer be able to interact with you through AMORA."))return;const{error}=await supabase.from("blocks").insert({blocker_id:session.user.id,blocked_id:id});setNotice(error?.message||"Member blocked.");if(!error)await load()};const isOnline=id=>presence.some(p=>p.user_id===id&&Date.now()-new Date(p.last_seen_at).getTime()<120000);const memberIds=new Set(people.map(p=>p.id));const matches=search.trim()?[]:[];return <div className="room-call-actions"><small>ROOM MEMBERS</small>{notice&&<div className="discover-notice">{notice}</div>}<div className="room-invite-panel"><strong>Invite someone</strong><input value={search} placeholder="Search eligible members by name" onChange={e=>setSearch(e.target.value)}/>{search.trim()&&<InviteSearch room={room} session={session} query={search} existingIds={new Set([...memberIds,...pending.map(x=>x.invitee_id)])} onInvite={invite} inviting={inviting}/>}</div>{pending.length>0&&<div className="room-pending-invites"><small>PENDING INVITATIONS</small>{pending.map(i=><PendingInvite key={i.invitee_id} invite={i} revoking={revoking} onRevoke={revoke}/>)}</div>}{busy?<p className="setting-note">Loading room members…</p>:people.length===0?<p className="setting-note">No other active room members yet.</p>:people.map(p=><div className="account-setting-row" key={p.id}><span><strong>{p.display_name||"AMORA member"}</strong><small>{isOnline(p.id)?"● Online":"○ Away"} · {p.allow_calls?"Calls available":"Calls disabled"}</small></span><span className="call-actions-inline"><button className="ghost" disabled={!room.voice_enabled||!p.allow_calls||!isOnline(p.id)} onClick={()=>call(p.id,"voice")}>Voice</button><button className="primary" disabled={!room.video_enabled||!p.allow_calls||!isOnline(p.id)} onClick={()=>call(p.id,"video")}>Video</button><button className="ghost" onClick={()=>report(p.id)}>Report</button><button className="ghost" onClick={()=>block(p.id)}>Block</button></span></div>)}</div>}

function PendingInvite({invite,revoking,onRevoke}){const[name,setName]=useState("AMORA member");useEffect(()=>{supabase.from("profiles").select("display_name").eq("id",invite.invitee_id).maybeSingle().then(({data})=>data?.display_name&&setName(data.display_name))},[invite.invitee_id]);return <div className="account-setting-row"><span><strong>{name}</strong><small>Invitation pending · expires {new Date(invite.expires_at).toLocaleDateString()}</small></span><button className="ghost" disabled={revoking===invite.invitee_id} onClick={()=>onRevoke(invite.invitee_id)}>{revoking===invite.invitee_id?"Revoking…":"Revoke"}</button></div>}

function InviteSearch({room,session,query,existingIds,onInvite,inviting}){const[results,setResults]=useState([]),[busy,setBusy]=useState(true);useEffect(()=>{let live=true;(async()=>{setBusy(true);const{data}=await supabase.from("discoverable_profiles").select("id,display_name,age,city,country_code,verification_status").neq("id",session.user.id).ilike("display_name","%"+query+"%").limit(8);if(live)setResults((data||[]).filter(x=>!existingIds.has(x.id)));setBusy(false)})();return()=>{live=false}},[query,session.user.id]);if(busy)return <small>Searching…</small>;if(!results.length)return <small>No eligible members found.</small>;return <div className="invite-search-results">{results.map(p=><div className="account-setting-row" key={p.id}><span><strong>{p.display_name||"AMORA member"}</strong><small>{p.age}{p.city?", "+p.city:""}{p.verification_status!=="unverified"?" · Verified":""}</small></span><button className="primary" disabled={inviting===p.id} onClick={()=>onInvite(p.id)}>{inviting===p.id?"Sending…":"Invite"}</button></div>)}</div>}

function RoomSettings({session}){const[room,setRoom]=useState(null),[busy,setBusy]=useState(true),[saving,setSaving]=useState(false),[notice,setNotice]=useState("");useEffect(()=>{supabase.from("rooms").select("*").eq("owner_id",session.user.id).maybeSingle().then(({data,error})=>{setRoom(data||null);if(error)setNotice(error.message);setBusy(false)})},[session.user.id]);const save=async()=>{if(!room)return;setSaving(true);const{error}=await supabase.from("rooms").update({name:room.name,description:room.description,chat_enabled:room.chat_enabled,voice_enabled:room.voice_enabled,video_enabled:room.video_enabled,requires_invitation:room.requires_invitation,requires_subscription:room.requires_subscription}).eq("id",room.id);setNotice(error?error.message:"Room settings saved.");setSaving(false)};if(busy)return <div className="empty-panel"><h3>Loading room settings…</h3></div>;if(!room)return <div className="empty-panel"><h3>Create your room first.</h3><p>Open My Room to create your premium private room.</p></div>;return <div className="settings-card">{notice&&<div className="discover-notice">{notice}</div>}<label className="field">Room name<input value={room.name} onChange={e=>setRoom({...room,name:e.target.value})}/></label><label className="field">Description<textarea value={room.description||""} onChange={e=>setRoom({...room,description:e.target.value})}/></label><div className="setting-grid">{[["chat_enabled","Chat"],["voice_enabled","Voice calls"],["video_enabled","Video calls"],["requires_invitation","Invitation required"]].map(([key,label])=><label className="setting-toggle" key={key}><input type="checkbox" checked={!!room[key]} onChange={e=>setRoom({...room,[key]:e.target.checked})}/><span>{label}</span></label>)}</div><button className="primary" disabled={saving} onClick={save}>{saving?"Saving…":"Save room settings"}</button></div>}

